window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d4c46acef35f5be8"]={"versions": [{"id": "FIG-d4c46acef35f5be8", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Integrationsdiagramm zur Veranschaulichung des zweistufigen Integrationsablaufs von BSW-Modulen im Kontext der AUTOSAR Classic Platform. Das Diagramm modelliert die organisatorische und datenflusstechnische Trennung zwischen der Entwicklungsumgebung der Modulzulieferer (AUTOSAR Module Suppliers) und der Integrationsumgebung des Systemintegrators (AUTOSAR Integrator) mit speziellem Fokus auf Compiler-Abstraktion (<code>Compiler.h</code>, <code>Compiler_Cfg.h</code>) und Speicherkonfiguration (<code>MemMap.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei primäre Akteure bzw. Rollen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Module Suppliers</strong> (mehrfach geschichtet dargestellt für n Zulieferer) in der <strong>Development Environment</strong>.</li>\n<li><strong>AUTOSAR Integrator</strong> in der <strong>Integration Environment</strong>.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Basisdateien (Schritt 1)</strong>: <code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Example of MemMap.h</code>.</li>\n<li><strong>Modullieferung / Package (Schritt 2)</strong>: Aggregation bestehend aus <code>Module source files</code>, modulspezifischem <code>Compiler_Cfg.h</code>, <code>MemMap.h</code> und <code>Documents</code>.</li>\n<li><strong>Integrationsartefakte (Integrator-Seite)</strong>: Modulspezifische Konfigurationsheader (<code>Compiler_Cfg.h of Module A</code>, <code>Compiler_Cfg.h of Module B</code>, <code>Compiler_Cfg.h of Module C</code>), die über einen Integrationsknoten (Zusammenführung/Aggregation) in die zentrale Datei <code>Compiler_Cfg.h</code> zusammengeführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei nummerierte Hauptschritte:</p>\n<ol class=\"fig-list\">\n<li><strong>Step 1: Delivery of basic files</strong>: Der Integrator übergibt grundlegende Header und Templates (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Example of MemMap.h</code>) an die Modulzulieferer.</li>\n<li><strong>Konstruktion im Lieferantenkontext</strong>: Die Modulzulieferer implementieren Quelltexte und Dokumente, weisen Versions- und Hersteller-IDs zu, erstellen die modulspezifischen Teile von <code>Compiler_Cfg.h</code> und <code>MemMap.h</code> und schnüren das Übergabepaket (<code>Package</code>).</li>\n<li><strong>Step 2: Delivery of modules</strong>: Parallele Übergabe der Modulpakete von mehreren Zulieferern an die Integrationsumgebung des Integrators.</li>\n<li><strong>Integration und Konfiguration im Integratorkontext</strong>: Der Integrator nimmt die Pakete entgegen, prüft sie, integriert die Module, führt die einzelnen <code>Compiler_Cfg.h</code>-Dateien der Module A, B, C in eine gemeinsame zentrale <code>Compiler_Cfg.h</code> zusammen, integriert die einzelnen <code>MemMap.h</code>-Dateien in eine zentrale <code>MemMap.h</code> und konfiguriert <code>MemMap.h</code> sowie <code>Compiler_Cfg.h</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptioneller Integrationsvorschlag ohne direkte normative Vorschrift für Buildsystem-Architekturen. Für Entwickler und Integratoren verdeutlicht das Diagramm die Verantwortlichkeiten bei Header-Dateien:</p>\n<ul class=\"fig-list\">\n<li>Modulentwickler dürfen in ihren Header-Lieferungen nur den modulspezifischen Anteil definieren.</li>\n<li>Der Integrator verantwortet die projektweite Konsolidierung und Vermeidung von Namensraum- oder Makrokonflikten beim Zusammenführen mehrerer modulspezifischer Header in die zentralen Projekt-Header <code>Compiler_Cfg.h</code> und <code>MemMap.h</code>.</li>\n</ul>"}, {"id": "FIG-1d6ad9a18478aa63", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Integrationsdiagramm zur Veranschaulichung des zweistufigen Integrationsablaufs von BSW-Modulen im Kontext der AUTOSAR Classic Platform. Das Diagramm modelliert die organisatorische und datenflusstechnische Trennung zwischen der Entwicklungsumgebung der Modulzulieferer (AUTOSAR Module Suppliers) und der Integrationsumgebung des Systemintegrators (AUTOSAR Integrator) mit speziellem Fokus auf Compiler-Abstraktion (<code>Compiler.h</code>, <code>Compiler_Cfg.h</code>) und Speicherkonfiguration (<code>MemMap.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei primäre Akteure bzw. Rollen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Module Suppliers</strong> (mehrfach geschichtet dargestellt für n Zulieferer) in der <strong>Development Environment</strong>.</li>\n<li><strong>AUTOSAR Integrator</strong> in der <strong>Integration Environment</strong>.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Basisdateien (Schritt 1)</strong>: <code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Example of MemMap.h</code>.</li>\n<li><strong>Modullieferung / Package (Schritt 2)</strong>: Aggregation bestehend aus <code>Module source files</code>, modulspezifischem <code>Compiler_Cfg.h</code>, <code>MemMap.h</code> und <code>Documents</code>.</li>\n<li><strong>Integrationsartefakte (Integrator-Seite)</strong>: Modulspezifische Konfigurationsheader (<code>Compiler_Cfg.h of Module A</code>, <code>Compiler_Cfg.h of Module B</code>, <code>Compiler_Cfg.h of Module C</code>), die über einen Integrationsknoten (Zusammenführung/Aggregation) in die zentrale Datei <code>Compiler_Cfg.h</code> zusammengeführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei nummerierte Hauptschritte:</p>\n<ol class=\"fig-list\">\n<li><strong>Step 1: Delivery of basic files</strong>: Der Integrator übergibt grundlegende Header und Templates (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Example of MemMap.h</code>) an die Modulzulieferer.</li>\n<li><strong>Konstruktion im Lieferantenkontext</strong>: Die Modulzulieferer implementieren Quelltexte und Dokumente, weisen Versions- und Hersteller-IDs zu, erstellen die modulspezifischen Teile von <code>Compiler_Cfg.h</code> und <code>MemMap.h</code> und schnüren das Übergabepaket (<code>Package</code>).</li>\n<li><strong>Step 2: Delivery of modules</strong>: Parallele Übergabe der Modulpakete von mehreren Zulieferern an die Integrationsumgebung des Integrators.</li>\n<li><strong>Integration und Konfiguration im Integratorkontext</strong>: Der Integrator nimmt die Pakete entgegen, prüft sie, integriert die Module, führt die einzelnen <code>Compiler_Cfg.h</code>-Dateien der Module A, B, C in eine gemeinsame zentrale <code>Compiler_Cfg.h</code> zusammen, integriert die einzelnen <code>MemMap.h</code>-Dateien in eine zentrale <code>MemMap.h</code> und konfiguriert <code>MemMap.h</code> sowie <code>Compiler_Cfg.h</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptioneller Integrationsvorschlag ohne direkte normative Vorschrift für Buildsystem-Architekturen. Für Entwickler und Integratoren verdeutlicht das Diagramm die Verantwortlichkeiten bei Header-Dateien:</p>\n<ul class=\"fig-list\">\n<li>Modulentwickler dürfen in ihren Header-Lieferungen nur den modulspezifischen Anteil definieren.</li>\n<li>Der Integrator verantwortet die projektweite Konsolidierung und Vermeidung von Namensraum- oder Makrokonflikten beim Zusammenführen mehrerer modulspezifischer Header in die zentralen Projekt-Header <code>Compiler_Cfg.h</code> und <code>MemMap.h</code>.</li>\n</ul>"}, {"id": "FIG-4cac9327cdd863b8", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Integrationsdiagramm zur Veranschaulichung des zweistufigen Integrationsablaufs von BSW-Modulen im Kontext der AUTOSAR Classic Platform. Das Diagramm modelliert die organisatorische und datenflusstechnische Trennung zwischen der Entwicklungsumgebung der Modulzulieferer (AUTOSAR Module Suppliers) und der Integrationsumgebung des Systemintegrators (AUTOSAR Integrator) mit speziellem Fokus auf Compiler-Abstraktion (<code>Compiler.h</code>, <code>Compiler_Cfg.h</code>) und Speicherkonfiguration (<code>MemMap.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei primäre Akteure bzw. Rollen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Module Suppliers</strong> (mehrfach geschichtet dargestellt für n Zulieferer) in der <strong>Development Environment</strong>.</li>\n<li><strong>AUTOSAR Integrator</strong> in der <strong>Integration Environment</strong>.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Basisdateien (Schritt 1)</strong>: <code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Example of MemMap.h</code>.</li>\n<li><strong>Modullieferung / Package (Schritt 2)</strong>: Aggregation bestehend aus <code>Module source files</code>, modulspezifischem <code>Compiler_Cfg.h</code>, <code>MemMap.h</code> und <code>Documents</code>.</li>\n<li><strong>Integrationsartefakte (Integrator-Seite)</strong>: Modulspezifische Konfigurationsheader (<code>Compiler_Cfg.h of Module A</code>, <code>Compiler_Cfg.h of Module B</code>, <code>Compiler_Cfg.h of Module C</code>), die über einen Integrationsknoten (Zusammenführung/Aggregation) in die zentrale Datei <code>Compiler_Cfg.h</code> zusammengeführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei nummerierte Hauptschritte:</p>\n<ol class=\"fig-list\">\n<li><strong>Step 1: Delivery of basic files</strong>: Der Integrator übergibt grundlegende Header und Templates (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Example of MemMap.h</code>) an die Modulzulieferer.</li>\n<li><strong>Konstruktion im Lieferantenkontext</strong>: Die Modulzulieferer implementieren Quelltexte und Dokumente, weisen Versions- und Hersteller-IDs zu, erstellen die modulspezifischen Teile von <code>Compiler_Cfg.h</code> und <code>MemMap.h</code> und schnüren das Übergabepaket (<code>Package</code>).</li>\n<li><strong>Step 2: Delivery of modules</strong>: Parallele Übergabe der Modulpakete von mehreren Zulieferern an die Integrationsumgebung des Integrators.</li>\n<li><strong>Integration und Konfiguration im Integratorkontext</strong>: Der Integrator nimmt die Pakete entgegen, prüft sie, integriert die Module, führt die einzelnen <code>Compiler_Cfg.h</code>-Dateien der Module A, B, C in eine gemeinsame zentrale <code>Compiler_Cfg.h</code> zusammen, integriert die einzelnen <code>MemMap.h</code>-Dateien in eine zentrale <code>MemMap.h</code> und konfiguriert <code>MemMap.h</code> sowie <code>Compiler_Cfg.h</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptioneller Integrationsvorschlag ohne direkte normative Vorschrift für Buildsystem-Architekturen. Für Entwickler und Integratoren verdeutlicht das Diagramm die Verantwortlichkeiten bei Header-Dateien:</p>\n<ul class=\"fig-list\">\n<li>Modulentwickler dürfen in ihren Header-Lieferungen nur den modulspezifischen Anteil definieren.</li>\n<li>Der Integrator verantwortet die projektweite Konsolidierung und Vermeidung von Namensraum- oder Makrokonflikten beim Zusammenführen mehrerer modulspezifischer Header in die zentralen Projekt-Header <code>Compiler_Cfg.h</code> und <code>MemMap.h</code>.</li>\n</ul>"}, {"id": "FIG-8451d5df1cb6a56e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Integrationsdiagramm zur Veranschaulichung des zweistufigen Integrationsablaufs von BSW-Modulen und Software-Komponenten im Kontext der AUTOSAR Classic Platform. Das Diagramm modelliert die organisatorische und datenflusstechnische Trennung zwischen der Entwicklungsumgebung der Modulzulieferer (AUTOSAR Module Suppliers) und der Integrationsumgebung des Systemintegrators (AUTOSAR Integrator) mit Fokus auf Compiler-Abstraktion (<code>Compiler.h</code>, <code>Compiler_Cfg.h</code>) und modulspezifisches Speichergapping (<code>&lt;Mip&gt;_MemMap.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei primäre Akteure bzw. Rollen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Module Suppliers</strong> (mehrfach geschichtet dargestellt für n Zulieferer) in der <strong>Development Environment</strong>.</li>\n<li><strong>AUTOSAR Integrator</strong> in der <strong>Integration Environment</strong>.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Basisdateien (Schritt 1)</strong>: <code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>.</li>\n<li><strong>Modullieferung / Package (Schritt 2)</strong>: Aggregation bestehend aus <code>Module source files</code>, modulspezifischem <code>Compiler_Cfg.h</code>, <code>Memory</code> (<code>&lt;Mip&gt;_MemMap.h</code>) und <code>Documents</code>.</li>\n<li><strong>Integrationsartefakte (Integrator-Seite)</strong>: Modulspezifische Konfigurationsheader (<code>Compiler_Cfg.h of Module A</code>, <code>Compiler_Cfg.h of Module B</code>, <code>Compiler_Cfg.h of Module C</code>), die über einen Integrationsknoten in die zentrale Datei <code>Compiler_Cfg.h</code> überführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei nummerierte Hauptschritte:</p>\n<ol class=\"fig-list\">\n<li><strong>Step 1: Delivery of basic files</strong>: Der Integrator stellt den Modulzulieferern die standardisierten Basiskopfdateien (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>) bereit.</li>\n<li><strong>Konstruktion im Lieferantenkontext</strong>: Die Modulzulieferer implementieren Quelltexte und Dokumentationen, weisen Versions- und Hersteller-IDs zu, implementieren die modulspezifischen Teile von <code>Compiler_Cfg.h</code> und <code>&lt;Mip&gt;_MemMap.h</code> und packen das Lieferpaket (<code>Package</code>).</li>\n<li><strong>Step 2: Delivery of modules / components</strong>: Parallele Übergabe der Modul- und Komponentenpakete mehrerer Zulieferer an die Integrationsumgebung.</li>\n<li><strong>Integration und Konfiguration im Integratorkontext</strong>: Der Integrator nimmt die Pakete entgegen, prüft diese, integriert die Module, führt die einzelnen <code>Compiler_Cfg.h</code>-Dateien der Module A, B, C in eine zentrale <code>Compiler_Cfg.h</code> zusammen und konfiguriert <code>&lt;Mip&gt;_MemMap.h</code> sowie <code>Compiler_Cfg.h</code>. Eine Konsolidierung einzelner MemMap-Dateien zu einer monolithischen zentralen Datei findet nicht statt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptioneller Integrationsvorschlag mit direkter Auswirkung auf Schnittstellen und Build-Regeln:</p>\n<ul class=\"fig-list\">\n<li>Der Wegfall einer zentral zusammengeführten <code>MemMap.h</code> spiegelt den Wechsel auf modulspezifisches Memory-Mapping (<code>&lt;Mip&gt;_MemMap.h</code>) wider.</li>\n<li>Lieferanten müssen <code>&lt;Mip&gt;_MemMap.h</code> pro Modul bereitstellen; der Integrator konfiguriert diese individuell, anstatt mehrere Dateien manuell zu einem gemeinsamen Header zu verschmelzen.</li>\n<li><code>Compiler_Cfg.h</code> verbleibt als konsolidierte Sammeldatei, in die die Zulieferer-Konfigurationsfragmente integriert werden.</li>\n</ul>"}, {"id": "FIG-30e3b855bdf882ee", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Integrationsdiagramm zur Veranschaulichung des zweistufigen Integrationsablaufs von BSW-Modulen und Software-Komponenten im Kontext der AUTOSAR Classic Platform. Das Diagramm modelliert die organisatorische und datenflusstechnische Trennung zwischen der Entwicklungsumgebung der Modulzulieferer (AUTOSAR Module Suppliers) und der Integrationsumgebung des Systemintegrators (AUTOSAR Integrator) mit Fokus auf Compiler-Abstraktion (<code>Compiler.h</code>, <code>Compiler_Cfg.h</code>) und modulspezifisches Speichergapping (<code>&lt;Mip&gt;_MemMap.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei primäre Akteure bzw. Rollen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Module Suppliers</strong> (mehrfach geschichtet dargestellt für n Zulieferer) in der <strong>Development Environment</strong>.</li>\n<li><strong>AUTOSAR Integrator</strong> in der <strong>Integration Environment</strong>.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Basisdateien (Schritt 1)</strong>: <code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>.</li>\n<li><strong>Modullieferung / Package (Schritt 2)</strong>: Aggregation bestehend aus <code>Module source files</code>, modulspezifischem <code>Compiler_Cfg.h</code>, <code>Memory</code> (<code>&lt;Mip&gt;_MemMap.h</code>) und <code>Documents</code>.</li>\n<li><strong>Integrationsartefakte (Integrator-Seite)</strong>: Modulspezifische Konfigurationsheader (<code>Compiler_Cfg.h of Module A</code>, <code>Compiler_Cfg.h of Module B</code>, <code>Compiler_Cfg.h of Module C</code>), die über einen Integrationsknoten in die zentrale Datei <code>Compiler_Cfg.h</code> überführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei nummerierte Hauptschritte:</p>\n<ol class=\"fig-list\">\n<li><strong>Step 1: Delivery of basic files</strong>: Der Integrator stellt den Modulzulieferern die standardisierten Basiskopfdateien (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>) bereit.</li>\n<li><strong>Konstruktion im Lieferantenkontext</strong>: Die Modulzulieferer implementieren Quelltexte und Dokumentationen, weisen Versions- und Hersteller-IDs zu, implementieren die modulspezifischen Teile von <code>Compiler_Cfg.h</code> und <code>&lt;Mip&gt;_MemMap.h</code> und packen das Lieferpaket (<code>Package</code>).</li>\n<li><strong>Step 2: Delivery of modules / components</strong>: Parallele Übergabe der Modul- und Komponentenpakete mehrerer Zulieferer an die Integrationsumgebung.</li>\n<li><strong>Integration und Konfiguration im Integratorkontext</strong>: Der Integrator nimmt die Pakete entgegen, prüft diese, integriert die Module, führt die einzelnen <code>Compiler_Cfg.h</code>-Dateien der Module A, B, C in eine zentrale <code>Compiler_Cfg.h</code> zusammen und konfiguriert <code>&lt;Mip&gt;_MemMap.h</code> sowie <code>Compiler_Cfg.h</code>. Eine Konsolidierung einzelner MemMap-Dateien zu einer monolithischen zentralen Datei findet nicht statt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptioneller Integrationsvorschlag mit direkter Auswirkung auf Schnittstellen und Build-Regeln:</p>\n<ul class=\"fig-list\">\n<li>Der Wegfall einer zentral zusammengeführten <code>MemMap.h</code> spiegelt den Wechsel auf modulspezifisches Memory-Mapping (<code>&lt;Mip&gt;_MemMap.h</code>) wider.</li>\n<li>Lieferanten müssen <code>&lt;Mip&gt;_MemMap.h</code> pro Modul bereitstellen; der Integrator konfiguriert diese individuell, anstatt mehrere Dateien manuell zu einem gemeinsamen Header zu verschmelzen.</li>\n<li><code>Compiler_Cfg.h</code> verbleibt als konsolidierte Sammeldatei, in die die Zulieferer-Konfigurationsfragmente integriert werden.</li>\n</ul>"}, {"id": "FIG-133d71f1d0e2a26a", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Prozess- und Integrationsdiagramm zur Veranschaulichung des zweistufigen Integrationsablaufs von BSW-Modulen und Software-Komponenten im Kontext der AUTOSAR Classic Platform. Das Diagramm modelliert die organisatorische und datenflusstechnische Trennung zwischen der Entwicklungsumgebung der Modulzulieferer (AUTOSAR Module Suppliers) und der Integrationsumgebung des Systemintegrators (AUTOSAR Integrator) mit Fokus auf Compiler-Abstraktion (<code>Compiler.h</code>, <code>Compiler_Cfg.h</code>) und modulspezifisches Speichergapping (<code>&lt;Mip&gt;_MemMap.h</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwei primäre Akteure bzw. Rollen:</p>\n<ul class=\"fig-list\">\n<li><strong>AUTOSAR Module Suppliers</strong> (mehrfach geschichtet dargestellt für n Zulieferer) in der <strong>Development Environment</strong>.</li>\n<li><strong>AUTOSAR Integrator</strong> in der <strong>Integration Environment</strong>.</li>\n</ul>\n<p class=\"fig-p\">Artefakte und Datenstrukturen:</p>\n<ul class=\"fig-list\">\n<li><strong>Basisdateien (Schritt 1)</strong>: <code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>.</li>\n<li><strong>Modullieferung / Package (Schritt 2)</strong>: Aggregation bestehend aus <code>Module source files</code>, modulspezifischem <code>Compiler_Cfg.h</code>, <code>Memory</code> (<code>&lt;Mip&gt;_MemMap.h</code>) und <code>Documents</code>.</li>\n<li><strong>Integrationsartefakte (Integrator-Seite)</strong>: Modulspezifische Konfigurationsheader (<code>Compiler_Cfg.h of Module A</code>, <code>Compiler_Cfg.h of Module B</code>, <code>Compiler_Cfg.h of Module C</code>), die über einen Integrationsknoten in die zentrale Datei <code>Compiler_Cfg.h</code> überführt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei nummerierte Hauptschritte:</p>\n<ol class=\"fig-list\">\n<li><strong>Step 1: Delivery of basic files</strong>: Der Integrator stellt den Modulzulieferern die standardisierten Basiskopfdateien (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>) bereit.</li>\n<li><strong>Konstruktion im Lieferantenkontext</strong>: Die Modulzulieferer implementieren Quelltexte und Dokumentationen, weisen Versions- und Hersteller-IDs zu, implementieren die modulspezifischen Teile von <code>Compiler_Cfg.h</code> und <code>&lt;Mip&gt;_MemMap.h</code> und packen das Lieferpaket (<code>Package</code>).</li>\n<li><strong>Step 2: Delivery of modules / components</strong>: Parallele Übergabe der Modul- und Komponentenpakete mehrerer Zulieferer an die Integrationsumgebung.</li>\n<li><strong>Integration und Konfiguration im Integratorkontext</strong>: Der Integrator nimmt die Pakete entgegen, prüft diese, integriert die Module, führt die einzelnen <code>Compiler_Cfg.h</code>-Dateien der Module A, B, C in eine zentrale <code>Compiler_Cfg.h</code> zusammen und konfiguriert <code>&lt;Mip&gt;_MemMap.h</code> sowie <code>Compiler_Cfg.h</code>. Eine Konsolidierung einzelner MemMap-Dateien zu einer monolithischen zentralen Datei findet nicht statt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptioneller Integrationsvorschlag mit direkter Auswirkung auf Schnittstellen und Build-Regeln:</p>\n<ul class=\"fig-list\">\n<li>Der Wegfall einer zentral zusammengeführten <code>MemMap.h</code> spiegelt den Wechsel auf modulspezifisches Memory-Mapping (<code>&lt;Mip&gt;_MemMap.h</code>) wider.</li>\n<li>Lieferanten müssen <code>&lt;Mip&gt;_MemMap.h</code> pro Modul bereitstellen; der Integrator konfiguriert diese individuell, anstatt mehrere Dateien manuell zu einem gemeinsamen Header zu verschmelzen.</li>\n<li><code>Compiler_Cfg.h</code> verbleibt als konsolidierte Sammeldatei, in die die Zulieferer-Konfigurationsfragmente integriert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-d4c46acef35f5be8", "to": "FIG-1d6ad9a18478aa63", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1d6ad9a18478aa63", "to": "FIG-4cac9327cdd863b8", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4cac9327cdd863b8", "to": "FIG-8451d5df1cb6a56e", "fr": "R3.2.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Schritt 1 (Basisdateien)</strong>: <code>Example of MemMap.h</code> entfällt aus der Übergabe der grundlegenden Header-Dateien (<code>Compiler.h</code>, <code>Std_Types.h</code>, <code>Platform_Types.h</code>).</li>\n<li><strong>Schritt 2 (Lieferung)</strong>: Bezeichnung präzisiert zu „Step 2: Delivery of modules / components“.</li>\n<li><strong>Lieferumfang & Paketierung</strong>: Das modulbezogene MemMap-Artefakt wird von generischem <code>MemMap.h</code> auf modulspezifisches <code>&lt;Mip&gt;_MemMap.h</code> umgestellt (im Paket-Diagramm als <code>Memory</code> beschriftet).</li>\n<li><strong>Rollen-Aufgaben Zulieferer</strong>: Umstellung der Implementierungsaufgabe von <code>Compiler_Cfg.h and MemMap.h</code> auf <code>Compiler_Cfg.h and &lt;Mip&gt;_MemMap.h</code>.</li>\n<li><strong>Rollen-Aufgaben Integrator</strong>: Die Aufgabe „Integrates the single MemMap.h files into main MemMap.h“ entfällt vollständig; die Konfigurationsaufgabe lautet nun „Configures <Mip>_MemMap.h and Compiler_Cfg.h“ statt zuvor „Configures MemMap.h and Compiler_Cfg.h“.</li>\n</ul>"}, {"from": "FIG-8451d5df1cb6a56e", "to": "FIG-30e3b855bdf882ee", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-30e3b855bdf882ee", "to": "FIG-133d71f1d0e2a26a", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
